import { createListenerMiddleware, isAnyOf } from '@reduxjs/toolkit';
import { login, logout } from './authSlice';

// 1. Create the listener
const listenerMiddleware = createListenerMiddleware();

// 2. Define what it listens for
listenerMiddleware.startListening({
  // Listen for EITHER login or logout actions
  matcher: isAnyOf(login, logout),

  // 3. The side effect to run when it hears the action
  effect: async (action, listenerApi) => {
    // Grab the current state of the auth slice
    const authState = listenerApi.getState().auth;

    // Sync the Redux state to the browser's LocalStorage!
    localStorage.setItem('authData', JSON.stringify(authState));
  }
});
